import { and, count, desc, eq, inArray, isNotNull, like, lt, ne, or, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, projectMembers, projects } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";
import type { SQL } from "drizzle-orm";

/**
 * The row-level half of the private-project rule. `viewerId` is `null` for an
 * actor who sees every private project (admin, owner, platform staff); for
 * anyone else a `private` project is kept only when they lead it or are on it.
 */
export function visibleToViewer(
  orgId: OrgId,
  viewerId: UserId | null,
): SQL | undefined {
  if (viewerId === null) return undefined;

  return or(
    ne(projects.visibility, "private"),
    eq(projects.leadId, viewerId),
    inArray(
      projects.id,
      getDb()
        .select({ projectId: projectMembers.projectId })
        .from(projectMembers)
        .where(
          and(
            orgPredicate(projectMembers.orgId, orgId),
            eq(projectMembers.userId, viewerId),
          ),
        ),
    ),
  );
}

/** Ids of the projects `viewerId` may see, for filtering rows that hang off a project. */
export function visibleProjectIds(orgId: OrgId, viewerId: UserId) {
  return getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(orgPredicate(projects.orgId, orgId), visibleToViewer(orgId, viewerId)),
    );
}

